  beginTrashMutation(datasetId,actor){return this.transaction(()=>{const existing=this.database.prepare("SELECT * FROM storage_mutations WHERE entity_type='dataset' AND entity_id=? AND status IN ('intent','fs_applied') ORDER BY created_at LIMIT 1").get(datasetId);if(existing)return existing.mutation_type==='trash'?this.storageMutation(existing):null;const dataset=this.getDataset(datasetId);if(!dataset||dataset.storageMode==='external_reference'||dataset.rootKey!=='datasets'||dataset.status==='trashed'||this.datasetReferences(datasetId)>0||this.activeDatasetOperations(datasetId)>0)return null;const id=crypto.randomUUID(),trashId=crypto.randomUUID(),t=now(),trashRelative=`dataset/${datasetId}-${trashId}`,allowAbsent=dataset.status==='draft'&&dataset.fileCount===0;this.database.prepare("INSERT INTO storage_mutations(id,mutation_type,entity_type,entity_id,trash_id,source_root_key,source_relative_path,destination_root_key,destination_relative_path,allow_absent_source,status,actor,created_at,updated_at) VALUES (?,'trash','dataset',?,?,?,?,'trash',?,?,'intent',?,?,?)").run(id,datasetId,trashId,dataset.rootKey,dataset.relativePath,trashRelative,allowAbsent?1:0,actor||null,t,t);return this.getStorageMutation(id);});}
