  beginRestoreMutation(trashId,actor){return this.transaction(()=>{const item=this.getTrash(trashId);if(!item||item.permanentlyDeletedAt)return null;const existing=this.database.prepare("SELECT * FROM storage_mutations WHERE entity_type=? AND entity_id=? AND status IN ('intent','fs_applied') ORDER BY created_at LIMIT 1").get(item.entityType,item.entityId);if(existing)return existing.mutation_type==='restore'&&existing.trash_id===trashId?this.storageMutation(existing):null;let rootKey,relativePath,allowAbsent=0;if(item.entityType==='dataset'){const dataset=this.getDataset(item.entityId);if(!dataset||dataset.storageMode==='external_reference'||dataset.rootKey!=='datasets'||dataset.status!=='trashed'||this.activeDatasetOperations(dataset.id)>0)return null;rootKey=dataset.rootKey;relativePath=dataset.relativePath;allowAbsent=item.relativePath===''?1:0;}else if(item.entityType==='output'){const row=this.database.prepare('SELECT * FROM model_outputs WHERE id=?').get(item.entityId);if(!row||row.status!=='trashed'||row.root_key!=='models')return null;rootKey=row.root_key;relativePath=row.relative_path;}else return null;const id=crypto.randomUUID(),t=now();this.database.prepare("INSERT INTO storage_mutations(id,mutation_type,entity_type,entity_id,trash_id,source_root_key,source_relative_path,destination_root_key,destination_relative_path,allow_absent_source,status,actor,created_at,updated_at) VALUES (?,'restore',?,?,?,'trash',?,?,?,?,'intent',?,?,?)").run(id,item.entityType,item.entityId,item.id,item.relativePath,rootKey,relativePath,allowAbsent,actor||null,t,t);return this.getStorageMutation(id);});}
  beginPurgeMutation(trashId,actor){return this.transaction(()=>{const item=this.getTrash(trashId);if(!item||item.permanentlyDeletedAt)return null;const existing=this.database.prepare("SELECT * FROM storage_mutations WHERE entity_type=? AND entity_id=? AND status IN ('intent','fs_applied') ORDER BY created_at LIMIT 1").get(item.entityType,item.entityId);if(existing)return existing.mutation_type==='purge'&&existing.trash_id===trashId?this.storageMutation(existing):null;if(item.entityType==='dataset'){const dataset=this.getDataset(item.entityId);if(!dataset||dataset.storageMode==='external_reference'||dataset.rootKey!=='datasets'||dataset.status!=='trashed'||this.activeDatasetOperations(dataset.id)>0)return null;}else if(item.entityType==='output'){const output=this.getModelOutput(item.entityId);if(!output||output.status!=='trashed')return null;}else return null;const id=crypto.randomUUID(),t=now();this.database.prepare("INSERT INTO storage_mutations(id,mutation_type,entity_type,entity_id,trash_id,source_root_key,source_relative_path,status,actor,created_at,updated_at) VALUES (?,'purge',?,?,?,'trash',?,'intent',?,?,?)").run(id,item.entityType,item.entityId,item.id,item.relativePath,actor||null,t,t);return this.getStorageMutation(id);});}
  retryStorageMutation(id,actorId=null){return this.transaction(()=>{const mutation=this.getStorageMutation(id);if(!mutation||mutation.status!=='failed')return null;const active=this.database.prepare("SELECT id FROM storage_mutations WHERE entity_type=? AND entity_id=? AND status IN ('intent','fs_applied') LIMIT 1").get(mutation.entityType,mutation.entityId);if(active)return null;const t=now(),changed=this.database.prepare("UPDATE storage_mutations SET status='intent',error_code=NULL,error_message=NULL,completed_at=NULL,updated_at=? WHERE id=? AND status='failed'").run(t,id);if(changed.changes!==1)return null;this.insertAudit({actorId,action:'storage.lifecycle_retry_requested',entityType:mutation.entityType,entityId:mutation.entityId,details:{mutationId:id,type:mutation.type}});return this.getStorageMutation(id);});}
