  createUpload(input) {
    const id = crypto.randomUUID(); const token = crypto.randomBytes(32).toString('base64url'); const timestamp = now();
    this.database.prepare(`INSERT INTO upload_sessions(id,dataset_id,token_hash,subject,expected_manifest_json,chunk_size,status,expires_at,created_at,updated_at)
      VALUES (?,?,?,?,?,?,'open',?,?,?)`).run(id, input.datasetId, crypto.createHash('sha256').update(token).digest('hex'), input.subject, JSON.stringify(input.files), input.chunkSize,
      input.expiresAt, timestamp, timestamp);
    return { upload: this.getUpload(id), token };
  }
  resumeUpload(datasetId, subject, files, expiresAt) { const expected=JSON.stringify(files),row=this.database.prepare("SELECT * FROM upload_sessions WHERE dataset_id=? AND subject=? AND expected_manifest_json=? AND status='open' AND expires_at>? ORDER BY created_at DESC LIMIT 1").get(datasetId,subject,expected,now());if(!row)return null;const token=crypto.randomBytes(32).toString('base64url'),t=now();this.database.prepare('UPDATE upload_sessions SET token_hash=?,expires_at=?,updated_at=? WHERE id=?').run(crypto.createHash('sha256').update(token).digest('hex'),expiresAt,t,row.id);return{upload:this.getUpload(row.id),token}; }
  getUpload(id) { const r = this.database.prepare('SELECT * FROM upload_sessions WHERE id=?').get(id); return r && { id:r.id,datasetId:r.dataset_id,tokenHash:r.token_hash,subject:r.subject,files:json(r.expected_manifest_json,[]),chunkSize:r.chunk_size,status:r.status,expiresAt:r.expires_at,createdAt:r.created_at,updatedAt:r.updated_at }; }
  verifyUploadToken(upload, token) { return Boolean(upload && token && crypto.timingSafeEqual(Buffer.from(upload.tokenHash), Buffer.from(crypto.createHash('sha256').update(token).digest('hex')))); }
  recordChunk(input) {
    const existing = this.database.prepare('SELECT * FROM upload_chunks WHERE upload_id=? AND file_id=? AND chunk_index=?').get(input.uploadId,input.fileId,input.chunkIndex);
    if (existing) {
      if (existing.sha256 !== input.sha256 || existing.byte_size !== input.byteSize) throw Object.assign(new Error('chunk replay does not match'), { code:'chunk_conflict' });
      return { ...input, replayed:true };
    }
    this.database.prepare(`INSERT INTO upload_chunks(upload_id,file_id,chunk_index,byte_size,sha256,relative_path,created_at) VALUES (?,?,?,?,?,?,?)`).run(
      input.uploadId,input.fileId,input.chunkIndex,input.byteSize,input.sha256,input.relativePath,now());
    return { ...input, replayed:false };
  }
  listChunks(uploadId, fileId) { return this.database.prepare('SELECT * FROM upload_chunks WHERE upload_id=? AND file_id=? ORDER BY chunk_index').all(uploadId,fileId); }
  claimUploadFinalization(id) { const t=now();return this.database.prepare("UPDATE upload_sessions SET status='finalizing',updated_at=? WHERE id=? AND status='open'").run(t,id).changes===1; }
  reopenUpload(id) { this.database.prepare("UPDATE upload_sessions SET status='open',updated_at=? WHERE id=? AND status='finalizing'").run(now(),id); }
  completeUpload(id) { const t=now(); this.database.prepare("UPDATE upload_sessions SET status='complete',updated_at=? WHERE id=?").run(t,id); return this.getUpload(id); }
  expiredUploads(at=Date.now()){return this.database.prepare("SELECT id FROM upload_sessions WHERE status IN ('open','expired','cancelled') AND expires_at<=?").all(new Date(at).toISOString()).map((r)=>r.id);}
