  provider(row) { return row && { id:row.id,type:row.provider_type,displayName:row.display_name,endpoint:row.endpoint,enabled:Boolean(row.enabled),admissionLimit:row.admission_limit,activeAttempts:this.activeProviderAttempts(row.id),capabilities:json(row.capabilities_json),capabilityFingerprint:row.capability_fingerprint,lastHealth:row.last_health,lastHealthAt:row.last_health_at,runtimeHealth:row.runtime_health||null,runtimeHealthAt:row.runtime_health_at||null,runtimeHealthError:row.runtime_health_error||null,credential:{configured:Boolean(row.credential_ciphertext),updatedAt:row.credential_updated_at||null},createdAt:row.created_at,updatedAt:row.updated_at }; }
