  listProvidersPage({limit=50,cursor=null}={}) { const n=pageLimit(limit),c=decodeCursor(cursor);const rows=c?this.database.prepare('SELECT * FROM processing_providers WHERE created_at<? OR (created_at=? AND id<?) ORDER BY created_at DESC,id DESC LIMIT ?').all(c.createdAt,c.createdAt,c.id,n+1):this.database.prepare('SELECT * FROM processing_providers ORDER BY created_at DESC,id DESC LIMIT ?').all(n+1);const more=rows.length>n,items=rows.slice(0,n);return{items:items.map((r)=>this.provider(r)),nextCursor:more?encodeCursor(items.at(-1)):null}; }
