  updateProviderMetadata(id,input,audit=null) { return this.transaction(()=>{const current=this.getProvider(id);if(!current)return null;const endpoint=String(input.endpoint??current.endpoint).replace(/\/+$/,''),changedEndpoint=endpoint!==current.endpoint,t=now();if(changedEndpoint&&this.activeProviderAttempts(id)>0)throw Object.assign(new Error('provider has active attempts'),{code:'provider_in_use'});const enabled=changedEndpoint?false:(input.enabled===undefined?current.enabled:input.enabled);if(enabled){const credential=this.getProviderCredential(id);if(!credential?.credentialCiphertext)throw Object.assign(new Error('provider credential is required'),{code:'provider_credential_required'});if(credential.lastHealth!=='healthy'||credential.lastProbeCredentialRevision===null||credential.lastProbeCredentialRevision!==credential.credentialRevision)throw Object.assign(new Error('provider probe is required'),{code:'provider_probe_required'});}this.database.prepare(`UPDATE processing_providers SET provider_type=?,display_name=?,endpoint=?,enabled=?,admission_limit=?,capabilities_json=CASE WHEN ? THEN '{}' ELSE capabilities_json END,capability_fingerprint=CASE WHEN ? THEN NULL ELSE capability_fingerprint END,last_health=CASE WHEN ? THEN NULL ELSE last_health END,last_health_at=CASE WHEN ? THEN NULL ELSE last_health_at END,last_probe_credential_revision=CASE WHEN ? THEN NULL ELSE last_probe_credential_revision END,updated_at=? WHERE id=?`).run(input.type??current.type,bounded(input.displayName??current.displayName),endpoint,enabled?1:0,input.admissionLimit??current.admissionLimit,changedEndpoint?1:0,changedEndpoint?1:0,changedEndpoint?1:0,changedEndpoint?1:0,changedEndpoint?1:0,t,id);const provider=this.getProvider(id);if(audit)this.insertAudit({...audit,entityId:id});return provider;}); }
  setProviderCredential(id,{ciphertext,keyId},audit=null) { return this.transaction(()=>{if(this.activeProviderAttempts(id)>0)throw Object.assign(new Error('provider has active attempts'),{code:'provider_in_use'});const t=now(),changed=this.database.prepare(`UPDATE processing_providers SET credential_ciphertext=?,credential_key_id=?,credential_updated_at=?,credential_revision=credential_revision+1,credential_cleared=0,enabled=0,capabilities_json='{}',capability_fingerprint=NULL,last_health=NULL,last_health_at=NULL,last_probe_credential_revision=NULL,updated_at=? WHERE id=?`).run(ciphertext,keyId,t,t,id);if(!changed.changes)return null;if(audit)this.insertAudit({...audit,entityId:id});return this.getProvider(id);}); }
