  clearProviderCredential(id,audit=null) { return this.transaction(()=>{if(this.activeProviderAttempts(id)>0)throw Object.assign(new Error('provider has active attempts'),{code:'provider_in_use'});const t=now(),changed=this.database.prepare(`UPDATE processing_providers SET credential_ciphertext=NULL,credential_key_id=NULL,credential_updated_at=NULL,credential_revision=credential_revision+1,credential_cleared=1,enabled=0,capabilities_json='{}',capability_fingerprint=NULL,last_health=NULL,last_health_at=NULL,last_probe_credential_revision=NULL,updated_at=? WHERE id=?`).run(t,id);if(!changed.changes)return null;if(audit)this.insertAudit({...audit,entityId:id});return this.getProvider(id);}); }
  providerProbeCurrent(id) { const row=this.database.prepare("SELECT credential_revision,last_probe_credential_revision,last_health FROM processing_providers WHERE id=?").get(id);return Boolean(row&&row.last_health==='healthy'&&row.last_probe_credential_revision!==null&&Number(row.last_probe_credential_revision)===Number(row.credential_revision)); }
